    #[test]
    fn ifccolumn_generation_with_rotation_vectors_and_check() {
        let building = Building {
            name: "ColumnBuilding".to_string(),
            timestamp: 123456,
            storeys: vec![BuildingStorey {
                name: "Storey 1".to_string(),
                elevation: 0.0,
                height: 2.80,
                walls: Vec::new(),
                slabs: Vec::new(),
                zones: Vec::new(),
                openings: Vec::new(),
                columns: vec![
                    Column {
                        center: [2.0, 3.0],
                        base_z: 0.0,
                        height: 2.80,
                        shape: ColumnShape::Rectangular { width: 0.50, depth: 0.30, rotation_deg: 45.0 },
                    },
                    Column { center: [5.0, 5.0], base_z: 0.0, height: 2.80, shape: ColumnShape::Circular { diameter: 0.40 } },
                ],
                stairs: Vec::new(),
            }],
        };

        let step = write(&building).expect("write IFC with columns");
        assert!(step.contains("IFCCOLUMN"));
        assert!(step.contains("IFCRECTANGLEPROFILEDEF"));
        assert!(step.contains("IFCCIRCLEPROFILEDEF"));
        // 45 degrees: cos(45 deg) = sin(45 deg) = ~0.707107
        assert!(step.contains("0.707107"));

        let chk = check(&step).expect("check passes without dangling refs");
        assert_eq!(chk.columns, 2);
    }

    #[test]
    fn ifc_writes_curved_wall_and_closed_door() {
        let building = Building {
            name: "CurvedAndClosed".to_string(),
            timestamp: 1_761_350_400,
            storeys: vec![BuildingStorey {
                name: "Ground".to_string(),
                elevation: 0.0,
                height: 2.80,
                walls: vec![Wall {
                    from: [3.0, 0.0],
                    to: [0.0, 3.0],
                    thickness: 0.20,
                    base_z: 0.0,
                    height: 2.80,
                    exterior: false,
                    is_parapet: false,
                    arc: Some(WallArc { center: [0.0, 0.0], radius: 3.0, ccw: true }),
                }],
                slabs: Vec::new(),
                zones: Vec::new(),
                openings: vec![Opening {
                    wall: 0,
                    kind: OpeningKind::ClosedDoor { recess_depth: 0.035 },
                    shape: OpeningShape::Rectangular,
                    from: [2.5, 0.5],
                    to: [1.8, 1.2],
                    thickness: 0.20,
                    sill_z: 0.0,
                    head_z: 2.10,
                }],
                columns: Vec::new(),
                stairs: Vec::new(),
            }],
        };

        let step = write(&building).expect("write IFC with curved wall and closed door");
        assert!(step.contains("Curved wall R=3."));
        assert!(step.contains("Closed door recess=0.035m"));
        assert!(step.contains("IFCDOOR"));
        assert!(step.contains("IFCWALL"));

        let chk = check(&step).expect("check passes without dangling refs");
        assert_eq!(chk.walls, 1);
        assert_eq!(chk.doors, 1);
        assert_eq!(chk.openings, 1);
    }

    #[test]
    fn ifc_writes_slab_regions_and_stairs() {
        use crate::bim::slabs::SlabRegion;
        let building = Building {
            name: "SplitLevelAndStairs".to_string(),
            timestamp: 1_761_350_400,
            storeys: vec![BuildingStorey {
                name: "Storey 1".to_string(),
                elevation: 0.0,
                height: 2.80,
                walls: Vec::new(),
                slabs: vec![Slab {
                    base_z: -0.20,
                    top_z: 0.0,
                    thickness: 0.20,
                    polygon: vec![[0.0, 0.0], [8.0, 0.0], [8.0, 4.0], [0.0, 4.0]],
                    holes: Vec::new(),
                    single_sided: true,
                    regions: vec![
                        SlabRegion {
                            polygon: vec![[0.0, 0.0], [4.0, 0.0], [4.0, 4.0], [0.0, 4.0]],
                            base_z: -0.20,
                            top_z: 0.0,
                            is_sloped: false,
                            slope_deg: 0.0,
                        },
                        SlabRegion {
                            polygon: vec![[4.0, 0.0], [8.0, 0.0], [8.0, 4.0], [4.0, 4.0]],
                            base_z: 0.30,
                            top_z: 0.50,
                            is_sloped: true,
                            slope_deg: 5.7,
                        },
                    ],
                }],
                zones: Vec::new(),
                openings: Vec::new(),
                columns: Vec::new(),
                stairs: vec![Stair {
                    storey_index: 0,
                    base_z: 0.0,
                    top_z: 0.90,
                    num_risers: 5,
                    riser_height: 0.18,
                    tread_depth: 0.28,
                    flight_axis: [[1.30, 2.0], [2.42, 2.0]],
                    width: 1.0,
                }],
            }],
        };

        let step = write(&building).expect("write IFC with split levels and stairs");
        assert!(step.contains("IFCSLAB"));
        assert!(step.contains("Split level region 1"));
        assert!(step.contains("Sloped slab 5.7 deg"));
        assert!(step.contains("IFCSTAIRFLIGHT"));
        assert!(step.contains(".STRAIGHT."));

        let chk = check(&step).expect("check passes");
        assert_eq!(chk.slabs, 2, "two regions exported as separate slabs");
        assert_eq!(chk.stairs, 1, "one stair flight exported and counted");
    }
